/**
 * Particle Class for Interactive Hero Canvas Artwork
 * Reads source image, generates a pixel grid, and reacts to cursor hover
 * by dispersing in brand orange (#FF4D00) before snapping back via spring-mass physics.
 */
class Particle {
  constructor(x, y, color, size) {
    this.x = x + (Math.random() - 0.5) * 10;
    this.y = y + (Math.random() - 0.5) * 10;
    this.originX = x;
    this.originY = y;
    this.baseColor = color;
    this.color = color;
    this.density = (Math.random() * 25) + 5;
    this.size = size || 4;
  }

  update(mouse, brandOrange) {
    if (!mouse || mouse.x === null || mouse.x === -9999) {
      // Spring back to original position
      this.color = this.baseColor;
      if (this.x !== this.originX) {
        let dx = this.x - this.originX;
        this.x -= dx / 10;
      }
      if (this.y !== this.originY) {
        let dy = this.y - this.originY;
        this.y -= dy / 10;
      }
      return;
    }

    let dx = mouse.x - this.x;
    let dy = mouse.y - this.y;
    let distance = Math.sqrt(dx * dx + dy * dy);

    // Hover Interaction: Repel and color shift to Brand Orange
    if (distance < mouse.radius) {
      let forceDirectionX = dx / (distance || 1);
      let forceDirectionY = dy / (distance || 1);
      let force = (mouse.radius - distance) / mouse.radius;
      let directionX = forceDirectionX * force * this.density;
      let directionY = forceDirectionY * force * this.density;

      this.x -= directionX;
      this.y -= directionY;
      this.color = brandOrange || '#FF4D00';
    } else {
      // Spring back to original position
      this.color = this.baseColor;
      if (this.x !== this.originX) {
        let dx = this.x - this.originX;
        this.x -= dx / 10;
      }
      if (this.y !== this.originY) {
        let dy = this.y - this.originY;
        this.y -= dy / 10;
      }
    }
  }

  draw(ctx) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.size, this.size);
  }
}

class PixelSoulEngine {
  constructor() {
    this.canvas = null;
    this.ctx = null;
    this.particlesArray = [];
    this.animId = null;
    this.isVisible = true;
    this.mouse = { x: null, y: null, radius: 90 };
    this.PARTICLE_SIZE = 4;
    this.BRAND_ORANGE = '#FF4D00';
    this.LOGO_DATA_URI = 'data:image/png;base64,';
  }

  init() {
    this.initHeroCanvas();
    this.initPixelDissolves();
    this.initPixelCorners();
    this.initPixelScatters();
  }

  /* ==========================================================================
     1. HERO PIXEL MOSAIC CANVAS & PARTICLE SYSTEM (logo_2.png)
     ========================================================================== */
  initHeroCanvas() {
    this.canvas = document.getElementById('heroCanvas') || document.getElementById('hero-canvas');
    if (!this.canvas) return;

    this.ctx = this.canvas.getContext('2d', { willReadFrequently: true });
    if (!this.ctx) return;

    // Track mouse coordinates accurately
    const updateMousePos = (clientX, clientY) => {
      const rect = this.canvas.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        this.mouse.x = (clientX - rect.left) * (this.canvas.width / rect.width);
        this.mouse.y = (clientY - rect.top) * (this.canvas.height / rect.height);
      }
    };

    window.addEventListener('mousemove', (event) => {
      updateMousePos(event.clientX, event.clientY);
    });

    window.addEventListener('mouseleave', () => {
      this.mouse.x = null;
      this.mouse.y = null;
    });

    this.canvas.addEventListener('mouseleave', () => {
      this.mouse.x = null;
      this.mouse.y = null;
    });

    // Touch interaction
    this.canvas.addEventListener('touchmove', (e) => {
      if (e.touches && e.touches.length > 0) {
        updateMousePos(e.touches[0].clientX, e.touches[0].clientY);
      }
    }, { passive: true });

    this.canvas.addEventListener('touchend', () => {
      this.mouse.x = null;
      this.mouse.y = null;
    });

    // IntersectionObserver to pause when scrolled out of view
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        this.isVisible = entry.isIntersecting;
        if (this.isVisible && !document.hidden && !this.animId) {
          this.animate();
        }
      });
    }, { threshold: 0.05 });

    observer.observe(this.canvas);

    // Tab visibility handling
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        if (this.animId) {
          cancelAnimationFrame(this.animId);
          this.animId = null;
        }
      } else {
        if (this.isVisible && !this.animId) {
          this.animate();
        }
      }
    });

    this.initMosaic(this.LOGO_DATA_URI);
  }

  initMosaic(imageSource) {
    const image = new Image();
    image.src = imageSource || this.LOGO_DATA_URI;

    image.onload = () => {
      this.canvas.width = 500;
      this.canvas.height = 500;

      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      // Draw centered with padding
      this.ctx.drawImage(image, 30, 30, 440, 440);

      const pixels = this.ctx.getImageData(0, 0, this.canvas.width, this.canvas.height).data;
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

      this.particlesArray = [];
      const step = this.PARTICLE_SIZE;

      for (let y = 0; y < this.canvas.height; y += step) {
        for (let x = 0; x < this.canvas.width; x += step) {
          let index = (y * this.canvas.width + x) * 4;
          let alpha = pixels[index + 3];

          if (alpha > 80) {
            let r = pixels[index];
            let g = pixels[index + 1];
            let b = pixels[index + 2];
            let color = `rgb(${r},${g},${b})`;
            this.particlesArray.push(new Particle(x, y, color, step));
          }
        }
      }

      if (!this.animId) {
        this.animate();
      }
    };

    image.onerror = () => {
      if (imageSource !== this.LOGO_DATA_URI) {
        this.initMosaic(this.LOGO_DATA_URI);
      }
    };
  }

  animate() {
    if (!this.isVisible || document.hidden) {
      this.animId = null;
      return;
    }

    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    for (let i = 0; i < this.particlesArray.length; i++) {
      this.particlesArray[i].update(this.mouse, this.BRAND_ORANGE);
      this.particlesArray[i].draw(this.ctx);
    }
    this.animId = requestAnimationFrame(() => this.animate());
  }

  /* ==========================================================================
     2. PIXEL DISSOLVE TRANSITION BANDS
     ========================================================================== */
  initPixelDissolves() {
    const dissolves = document.querySelectorAll('.pixel-dissolve-edge');
    dissolves.forEach(el => {
      if (el.children.length > 0) return;
      const isDown = el.classList.contains('dissolve-down');
      const isInkToCream = el.classList.contains('ink-to-cream');

      const colorPrimary = isInkToCream || el.classList.contains('from-ink') ? '#141414' : '#F7F5F1';
      const colorAccent = '#FF4D00';

      let html = '<div class="pixel-dissolve-grid">';
      for (let r = 0; r < 4; r++) {
        html += '<div class="dissolve-row">';
        for (let c = 0; c < 48; c++) {
          const density = isDown ? (4 - r) / 4 : (r + 1) / 4;
          const show = Math.random() < density;
          const isAccent = Math.random() < 0.08;
          const bg = isAccent ? colorAccent : colorPrimary;
          const opacity = show ? (0.3 + Math.random() * 0.7) : 0;
          html += `<span class="pixel-dot" style="background:${bg}; opacity:${opacity};"></span>`;
        }
        html += '</div>';
      }
      html += '</div>';
      el.innerHTML = html;
    });
  }

  /* ==========================================================================
     3. PIXEL CORNER IMAGE FRAME ACCENTS
     ========================================================================== */
  initPixelCorners() {
    const frames = document.querySelectorAll('.pixel-corner-frame');
    frames.forEach(frame => {
      if (frame.querySelector('.pixel-corner-dots')) return;

      const cornerDots = document.createElement('div');
      cornerDots.className = 'pixel-corner-dots';
      cornerDots.innerHTML = `
        <span class="p-dot p-tl1"></span><span class="p-dot p-tl2"></span><span class="p-dot p-tl3"></span>
        <span class="p-dot p-tr1"></span><span class="p-dot p-tr2"></span>
        <span class="p-dot p-bl1"></span><span class="p-dot p-bl2"></span>
        <span class="p-dot p-br1"></span><span class="p-dot p-br2"></span><span class="p-dot p-br3"></span>
      `;
      frame.appendChild(cornerDots);
    });
  }

  /* ==========================================================================
     4. PIXEL SCATTER ACCENTS (Max 1 cluster per viewport)
     ========================================================================== */
  initPixelScatters() {
    const scatters = document.querySelectorAll('.pixel-scatter-cluster');
    scatters.forEach(cluster => {
      if (cluster.children.length > 0) return;
      const count = 5 + Math.floor(Math.random() * 4);
      let html = '';
      for (let i = 0; i < count; i++) {
        const isOrange = i === 0 || Math.random() < 0.35;
        const color = isOrange ? 'var(--orange)' : 'var(--ink)';
        const size = 4 + (i % 3) * 2;
        const op = 0.5 + Math.random() * 0.5;
        html += `<span class="scatter-pixel" style="width:${size}px; height:${size}px; background:${color}; opacity:${op};"></span>`;
      }
      cluster.innerHTML = html;
    });
  }
}

// Global instance
window.pixelSoul = new PixelSoulEngine();
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    window.pixelSoul.init();
  });
} else {
  window.pixelSoul.init();
}
